#!/usr/bin/env node
// Converts the readable source data (data/questions.csv, data/animals.csv, separator ";") into typed TypeScript
// (src/game/data.generated.ts). French typography is applied: no-break space before ? ! : ;
// English texts (v0.3.0): data/en/questions.csv (id;text) and data/en/animals.csv (id;name;spoken), same ids in the
// same order; the facts stay in data/animals.csv and are shared by both languages.
//
//   node scripts/build-data.mjs           # write src/game/data.generated.ts
//   node scripts/build-data.mjs --check   # exit 1 if the generated file is out of date
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'src', 'game', 'data.generated.ts');
const NBSP = ' ';

export function frenchTypography(text) {
  return text.replace(/[   ]*([?!:;])/g, `${NBSP}$1`);
}

function rows(file) {
  return fs
    .readFileSync(path.join(ROOT, 'data', ...file.split('/')), 'utf8')
    .split(/\r?\n/)
    .filter((l) => l.trim())
    .map((l) => l.split(';').map((c) => c.trim()));
}

export function buildData() {
  const [qHead, ...qRows] = rows('questions.csv');
  if (qHead.join(';') !== 'id;text') throw new Error('questions.csv header must be "id;text"');
  const questions = qRows.map(([id, text]) => ({ id, text: frenchTypography(text) }));
  const [aHead, ...aRows] = rows('animals.csv');
  const ids = aHead.slice(4);
  if (aHead.slice(0, 4).join(';') !== 'id;name;spoken;emoji') throw new Error('animals.csv must start with id;name;spoken;emoji');
  if (ids.join(';') !== questions.map((q) => q.id).join(';')) throw new Error('animals.csv question columns must match questions.csv order');
  const animals = aRows.map((r, i) => {
    if (r.length !== aHead.length) throw new Error(`animals.csv line ${i + 2}: ${r.length} columns, expected ${aHead.length}`);
    const [id, name, spoken, emoji, ...facts] = r;
    for (const f of facts) if (!['y', 'n', 'v'].includes(f)) throw new Error(`animals.csv line ${i + 2}: fact "${f}" is not y/n/v`);
    return { id, name, spoken, emoji, facts: facts.join('') };
  });
  const [eqHead, ...eqRows] = rows('en/questions.csv');
  if (eqHead.join(';') !== 'id;text') throw new Error('en/questions.csv header must be "id;text"');
  const [eaHead, ...eaRows] = rows('en/animals.csv');
  if (eaHead.join(';') !== 'id;name;spoken') throw new Error('en/animals.csv header must be "id;name;spoken"');
  const sameIds = (list, ref) => list.map((r) => r[0]).join(';') === ref.map((x) => x.id).join(';');
  if (!sameIds(eqRows, questions)) throw new Error('en/questions.csv ids must match questions.csv (same order)');
  if (!sameIds(eaRows, animals)) throw new Error('en/animals.csv ids must match animals.csv (same order)');
  const en = {
    questions: eqRows.map(([id, text]) => ({ id, text })),
    animals: eaRows.map(([id, name, spoken]) => ({ id, name, spoken })),
  };
  return { questions, animals, en };
}

export function render({ questions, animals, en }) {
  const q = questions.map((x) => `    { id: ${JSON.stringify(x.id)}, text: ${JSON.stringify(x.text)} },`).join('\n');
  const a = animals
    .map((x) => `    a(${[x.id, x.name, x.spoken, x.emoji, x.facts].map((v) => JSON.stringify(v)).join(', ')}),`)
    .join('\n');
  const eq = en.questions.map((x) => `  ${JSON.stringify(x.text)},`).join('\n');
  const ea = en.animals.map((x) => `  [${JSON.stringify(x.name)}, ${JSON.stringify(x.spoken)}],`).join('\n');
  return `// GENERATED by scripts/build-data.mjs from data/*.csv. Do not edit: edit the CSV files and re-run the script.
import { Animal, Fact, GameData } from './types';

const a = (id: string, name: string, spoken: string, emoji: string, facts: string): Animal => ({
  id,
  name,
  spoken,
  emoji,
  facts: facts.split('') as Fact[],
});

export const GAME_DATA: GameData = {
  questions: [
${q}
  ],
  animals: [
${a}
  ],
};

// English texts, in the same order as GAME_DATA (ids and facts are shared).
const EN_QUESTIONS: string[] = [
${eq}
];

const EN_ANIMALS: [name: string, spoken: string][] = [
${ea}
];

export const GAME_DATA_EN: GameData = {
  questions: GAME_DATA.questions.map((q, i) => ({ id: q.id, text: EN_QUESTIONS[i] })),
  animals: GAME_DATA.animals.map((x, i) => ({ ...x, name: EN_ANIMALS[i][0], spoken: EN_ANIMALS[i][1] })),
};

export const GAME_DATA_BY_LANGUAGE: Record<'fr' | 'en', GameData> = { fr: GAME_DATA, en: GAME_DATA_EN };
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const text = render(buildData());
    if (process.argv.includes('--check')) {
      const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
      if (current !== text) {
        console.error('data.generated.ts is out of date: run node scripts/build-data.mjs');
        process.exit(1);
      }
      console.log('data.generated.ts is up to date');
    } else {
      fs.writeFileSync(OUT, text, 'utf8');
      const d = buildData();
      console.log(`wrote ${path.relative(ROOT, OUT)}: ${d.animals.length} animals, ${d.questions.length} questions`);
    }
  } catch (err) {
    console.error(`build-data: ${err.message}`);
    process.exit(1);
  }
}
